INSERT INTO question (id, question, subtopic_id, difficulty, question_type) VALUES
  ('d0000000-0000-0000-0000-000000001101', 'Express 140 as a product of its prime factors.', 'c0000010-0001-0000-0000-000000000081', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001102', 'If two positive integers a and b are written as a = x^3 * y^2 and b = x * y^3, where x and y are prime numbers, then HCF(a, b) is:', 'c0000010-0001-0000-0000-000000000081', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001103', 'If LCM(p, q) = 360, HCF(p, q) = 12, and p = 72, find the value of q.', 'c0000010-0001-0000-0000-000000000081', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001104', 'The decimal expansion of the rational number 23 / (2^3 * 5^2) will terminate after how many decimal places?', 'c0000010-0001-0000-0000-000000000081', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001105', 'For any natural number n, with which of the following digits can 6^n never end?', 'c0000010-0001-0000-0000-000000000081', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001106', 'Which of the following numbers is a rational number?', 'c0000010-0001-0000-0000-000000000081', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001107', 'If HCF(a, b) = 1, then the pair of positive integers (a, b) is referred to as:', 'c0000010-0001-0000-0000-000000000081', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001108', 'Find the largest number which divides 70 and 125, leaving remainders 5 and 8 respectively.', 'c0000010-0001-0000-0000-000000000081', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001109', 'What is the LCM of the smallest two-digit composite number and the smallest composite number?', 'c0000010-0001-0000-0000-000000000081', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001110', 'State whether the product of a non-zero rational number and an irrational number is rational or irrational.', 'c0000010-0001-0000-0000-000000000081', 'Easy', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001111', 'What is the HCF of two consecutive natural numbers?', 'c0000010-0001-0000-0000-000000000081', 'Easy', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001112', 'If HCF(306, 657) = 9, calculate the value of LCM(306, 657).', 'c0000010-0001-0000-0000-000000000081', 'Medium', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001113', 'Find the least positive integer divisible by all numbers from 1 to 10 (both inclusive).', 'c0000010-0001-0000-0000-000000000081', 'Hard', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001114', 'If the discriminant D = b^2 - 4ac > 0 for quadratic equation ax^2 + bx + c = 0, the roots are:', 'c0000010-0001-0000-0000-000000000082', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001115', 'What is the discriminant of the quadratic equation 2x^2 - 4x + 3 = 0?', 'c0000010-0001-0000-0000-000000000082', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001116', 'For what non-zero value of k will the quadratic equation 2x^2 - kx + k = 0 have equal roots?', 'c0000010-0001-0000-0000-000000000082', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001117', 'If one root of the quadratic equation 2x^2 + kx - 6 = 0 is 2, find the value of k.', 'c0000010-0001-0000-0000-000000000082', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001118', 'The quadratic equation x^2 + 2(k + 2)x + 9k = 0 has equal roots. What are the values of k?', 'c0000010-0001-0000-0000-000000000082', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001119', 'If the roots of the quadratic equation ax^2 + bx + c = 0 are real and equal, each root is given by:', 'c0000010-0001-0000-0000-000000000082', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001120', 'For what values of p does the equation px^2 + 6x + 1 = 0 have no real roots?', 'c0000010-0001-0000-0000-000000000082', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001121', 'Which of the following is a quadratic equation?', 'c0000010-0001-0000-0000-000000000082', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001122', 'If alpha and beta are roots of x^2 - 5x + 6 = 0, find the value of alpha^2 + beta^2.', 'c0000010-0001-0000-0000-000000000082', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001123', 'State the condition on the discriminant D for ax^2 + bx + c = 0 to have two real and equal roots.', 'c0000010-0001-0000-0000-000000000082', 'Easy', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001124', 'Find the discriminant of the quadratic equation 3x^2 - 2x + 1/3 = 0.', 'c0000010-0001-0000-0000-000000000082', 'Medium', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001125', 'Find the non-zero value of k for which the quadratic equation kx(x - 2) + 6 = 0 has two equal roots.', 'c0000010-0001-0000-0000-000000000082', 'Hard', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001126', 'What is the value of sin^2(60 deg) + cos^2(60 deg)?', 'c0000010-0001-0000-0000-000000000083', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001127', 'What is the value of tan(30 deg) * cot(60 deg)?', 'c0000010-0001-0000-0000-000000000083', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001128', 'If cos(theta) = 4/5, what is the value of tan(theta)?', 'c0000010-0001-0000-0000-000000000083', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001129', 'Evaluate: (1 + tan^2(A)) / (1 + cot^2(A)).', 'c0000010-0001-0000-0000-000000000083', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001130', 'If sec(theta) + tan(theta) = x, what is the value of sec(theta) - tan(theta)?', 'c0000010-0001-0000-0000-000000000083', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001131', 'What is the value of 2 * tan(45 deg) * cos(60 deg)?', 'c0000010-0001-0000-0000-000000000083', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001132', 'If 4 tan(theta) = 3, evaluate (4 sin(theta) - cos(theta)) / (4 sin(theta) + cos(theta)).', 'c0000010-0001-0000-0000-000000000083', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001133', 'If sin(A) + sin^2(A) = 1, then the value of cos^2(A) + cos^4(A) is:', 'c0000010-0001-0000-0000-000000000083', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001134', 'What is the value of sin(90 deg) - cos(0 deg)?', 'c0000010-0001-0000-0000-000000000083', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001135', 'Simplify: (sec(A) + tan(A)) * (1 - sin(A)).', 'c0000010-0001-0000-0000-000000000083', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001136', 'What is the exact numerical value of sec(60 degrees)?', 'c0000010-0001-0000-0000-000000000083', 'Easy', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001137', 'If tan(A) = 1 for an acute angle A, find the value of 2 * sin(A) * cos(A).', 'c0000010-0001-0000-0000-000000000083', 'Medium', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001138', 'If 1 + sin^2(theta) = 3 * sin(theta) * cos(theta), state the values of tan(theta).', 'c0000010-0001-0000-0000-000000000083', 'Hard', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001139', 'In the Arithmetic Progression: 2, 7, 12, ..., what is the common difference d?', 'c0000010-0001-0000-0000-000000000084', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001140', 'What is the 10th term of the Arithmetic Progression: 5, 8, 11, 14, ...?', 'c0000010-0001-0000-0000-000000000084', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001141', 'Which term of the AP: 21, 18, 15, ... is -81?', 'c0000010-0001-0000-0000-000000000084', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001142', 'If the 3rd and 9th terms of an AP are 4 and -8 respectively, which term of this AP is 0?', 'c0000010-0001-0000-0000-000000000084', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001143', 'The sum of the first n terms of an AP is given by S_n = 3n^2 + 5n. Find its 15th term.', 'c0000010-0001-0000-0000-000000000084', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001144', 'Find the sum of the first 24 terms of the AP: 5, 2, -1, -4, ...', 'c0000010-0001-0000-0000-000000000084', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001145', 'How many terms of the AP: 24, 21, 18, ... must be taken so that their sum is 78?', 'c0000010-0001-0000-0000-000000000084', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001146', 'What is the sum of the first 100 positive integers?', 'c0000010-0001-0000-0000-000000000084', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001147', 'In an AP, if a = 3.5, d = 0, and n = 101, then a_n is:', 'c0000010-0001-0000-0000-000000000084', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001148', 'What is the common difference of an AP whose nth term is a_n = 3 + 4n?', 'c0000010-0001-0000-0000-000000000084', 'Easy', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001149', 'Find the 20th term from the end of the AP: 3, 8, 13, ..., 253.', 'c0000010-0001-0000-0000-000000000084', 'Medium', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001150', 'If the sum of the first 14 terms of an AP is 1050 and its first term is 10, find its 20th term.', 'c0000010-0001-0000-0000-000000000084', 'Hard', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001151', 'What type of chemical reaction is represented by: 2Mg(s) + O2(g) -> 2MgO(s)?', 'c0000010-0002-0000-0000-000000000085', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001152', 'Heating of limestone (CaCO3 -> CaO + CO2) is an example of which reaction?', 'c0000010-0002-0000-0000-000000000085', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001153', 'What happens when dilute hydrochloric acid is added to zinc granules?', 'c0000010-0002-0000-0000-000000000085', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001154', 'In the redox reaction: MnO2 + 4HCl -> MnCl2 + 2H2O + Cl2, which substance is oxidized?', 'c0000010-0002-0000-0000-000000000085', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001155', 'Which of the following processes is endothermic in nature?', 'c0000010-0002-0000-0000-000000000085', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001156', 'What type of reaction occurs when aqueous lead nitrate is mixed with potassium iodide solution?', 'c0000010-0002-0000-0000-000000000085', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001157', 'Fatty and oily food items develop an unpleasant smell and taste over time primarily due to:', 'c0000010-0002-0000-0000-000000000085', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001158', 'When copper powder is heated in air, its surface turns black due to the formation of:', 'c0000010-0002-0000-0000-000000000085', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001159', 'The reddish-brown flaky substance formed on iron articles exposed to moist air is chemically:', 'c0000010-0002-0000-0000-000000000085', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001160', 'Which of the following metals can readily displace copper from an aqueous solution of copper sulphate?', 'c0000010-0002-0000-0000-000000000085', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001161', 'Write the chemical formula of the white precipitate formed when sodium sulphate reacts with barium chloride.', 'c0000010-0002-0000-0000-000000000085', 'Easy', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001162', 'What gas is evolved with brisk effervescence when calcium carbonate reacts with dilute hydrochloric acid?', 'c0000010-0002-0000-0000-000000000085', 'Medium', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001163', 'Name the reducing agent in the thermite displacement reaction: Fe2O3 + 2Al -> Al2O3 + 2Fe.', 'c0000010-0002-0000-0000-000000000085', 'Hard', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001164', 'How many single covalent bonds are present in a molecule of methane (CH4)?', 'c0000010-0002-0000-0000-000000000086', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001165', 'Which allotrope of carbon is widely used as a dry industrial lubricant and in pencil cores?', 'c0000010-0002-0000-0000-000000000086', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001166', 'The unique ability of carbon atoms to form stable covalent bonds with other carbon atoms giving rise to large molecules is called:', 'c0000010-0002-0000-0000-000000000086', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001167', 'What is the molecular formula of the second member of the alkyne homologous series?', 'c0000010-0002-0000-0000-000000000086', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001168', 'What is the systematic IUPAC name of the compound CH3-CH2-COOH?', 'c0000010-0002-0000-0000-000000000086', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001169', 'How many structural isomers are possible for the alkane butane (C4H10)?', 'c0000010-0002-0000-0000-000000000086', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001170', 'Which organic functional group is present in the compound acetone (CH3-CO-CH3)?', 'c0000010-0002-0000-0000-000000000086', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001171', 'What is the carbon-carbon bond angle in the rigid three-dimensional tetrahedral lattice of diamond?', 'c0000010-0002-0000-0000-000000000086', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001172', 'When ethanol is heated with excess concentrated sulphuric acid at 443 K (170 deg C), what main product is formed?', 'c0000010-0002-0000-0000-000000000086', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001173', 'How many valence electrons does an isolated neutral carbon atom possess?', 'c0000010-0002-0000-0000-000000000086', 'Easy', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001174', 'Name the gas produced with effervescence when ethanoic acid reacts with sodium hydrogen carbonate.', 'c0000010-0002-0000-0000-000000000086', 'Medium', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001175', 'What is the common industrial name of the simplest alkyne, ethyne (C2H2)?', 'c0000010-0002-0000-0000-000000000086', 'Hard', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001176', 'What is the focal length of a spherical mirror whose radius of curvature is 30 cm?', 'c0000010-0002-0000-0000-000000000087', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001177', 'Where must an object be placed in front of a concave mirror to obtain an erect and enlarged virtual image?', 'c0000010-0002-0000-0000-000000000087', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001178', 'A convex mirror used on a bus has a radius of curvature of 3.0 m. If another vehicle is 5.0 m away, what is the image position?', 'c0000010-0002-0000-0000-000000000087', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001179', 'If the speed of light in water is 2.25 x 10^8 m/s and in vacuum is 3.0 x 10^8 m/s, find the refractive index of water.', 'c0000010-0002-0000-0000-000000000087', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001180', 'A convex lens forms a real image of the same size as the needle at 50 cm. Where is the needle located in front of the lens?', 'c0000010-0002-0000-0000-000000000087', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001181', 'What is the focal length and optical nature of a lens having power +2.0 D?', 'c0000010-0002-0000-0000-000000000087', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001182', 'A ray of light traveling in water falls obliquely on a glass slab (n_water = 1.33, n_glass = 1.50). How does the ray bend?', 'c0000010-0002-0000-0000-000000000087', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001183', 'Which optical phenomenon in the Earth''s atmosphere is responsible for the twinkling of stars?', 'c0000010-0002-0000-0000-000000000087', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001184', 'If the linear magnification produced by a spherical mirror is negative (m < 0), what does it signify about the image?', 'c0000010-0002-0000-0000-000000000087', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001185', 'If the absolute refractive indices of media A and B are 1.5 and 2.0 respectively, what is the refractive index of B with respect to A?', 'c0000010-0002-0000-0000-000000000087', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001186', 'What is the focal length of a flat plane mirror?', 'c0000010-0002-0000-0000-000000000087', 'Easy', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001187', 'State Snell''s mathematical law of refraction for light passing from medium 1 to medium 2.', 'c0000010-0002-0000-0000-000000000087', 'Medium', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001188', 'If two thin lenses of powers +3.5 D and -1.5 D are placed in close contact, what is the combined optical power?', 'c0000010-0002-0000-0000-000000000087', 'Hard', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001189', 'According to Ohm''s law, at constant temperature, the electric current flowing through a conductor is:', 'c0000010-0002-0000-0000-000000000088', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001190', 'What is the standard SI unit of electric charge?', 'c0000010-0002-0000-0000-000000000088', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001191', 'Three resistors of 2 ohms, 3 ohms, and 5 ohms are connected in series across a 10 V battery. What current flows through the circuit?', 'c0000010-0002-0000-0000-000000000088', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001192', 'A cylindrical wire of length L and cross-sectional area A has resistance R. What is the resistance of another wire of the same material of length 2L and area A/2?', 'c0000010-0002-0000-0000-000000000088', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001193', 'An electric heater consumes 840 W when heating at maximum rate on a 220 V supply. What is the current drawn?', 'c0000010-0002-0000-0000-000000000088', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001194', 'Which alloy is universally preferred for fabricating heating elements of appliances like toasters and room heaters?', 'c0000010-0002-0000-0000-000000000088', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001195', 'What is the equivalent resistance when n identical resistors, each having resistance R, are connected in parallel?', 'c0000010-0002-0000-0000-000000000088', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001196', 'An electric bulb is rated 220 V, 100 W. What is its operating electrical resistance?', 'c0000010-0002-0000-0000-000000000088', 'Easy', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001197', 'How much electrical energy in Joules is consumed by a 100 W bulb operated for 10 hours?', 'c0000010-0002-0000-0000-000000000088', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000001198', 'What instrument is always connected in series in a circuit to measure the flowing electric current?', 'c0000010-0002-0000-0000-000000000088', 'Easy', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001199', 'State Joule''s law of heating relating heat generated H to current I, resistance R, and time t.', 'c0000010-0002-0000-0000-000000000088', 'Medium', 'SAQ'),
  ('d0000000-0000-0000-0000-000000001200', 'Two electric bulbs rated 40 W and 60 W are connected in series across the mains. Which bulb glows brighter?', 'c0000010-0002-0000-0000-000000000088', 'Hard', 'SAQ')
